def block(start,end,new):
    global s
    i=s.index(start);j=s.index(end,i);s=s[:i]+new+s[j:]
def rep(a,b,c=1):
    global s
    assert s.count(a)==c,(a[:80],s.count(a));s=s.replace(a,b)

